SELECT 

FROM deposit_management
WHERE 1=1

    AND bidding_project_id = #{param.biddingProjectId}


    AND deposit_type = #{param.depositType}


    AND deposit_status = #{param.depositStatus}


    AND payment_method = #{param.paymentMethod}


    AND bank_name LIKE CONCAT('%', #{param.bankName}, '%')


    AND guarantee_no LIKE CONCAT('%', #{param.guaranteeNo}, '%')


    AND manager_id = #{param.managerId}


    AND manager_name LIKE CONCAT('%', #{param.managerName}, '%')


    AND deposit_amount >= #{param.minDepositAmount}


    AND deposit_amount <= #{param.maxDepositAmount}


    AND guarantee_start_date >= #{param.guaranteeStartDate}


    AND guarantee_end_date <= #{param.guaranteeEndDate}


    AND payment_date >= #{param.paymentStartDate}


    AND payment_date <= #{param.paymentEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (guarantee_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR bank_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR manager_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COALESCE(SUM(deposit_amount), 0)
FROM deposit_management
WHERE deposit_type = #{depositType}

SELECT COALESCE(SUM(deposit_amount), 0)
FROM deposit_management
WHERE bidding_project_id = #{biddingProjectId}

SELECT COUNT(*)
FROM deposit_management
WHERE deposit_status = #{depositStatus}

mapper.update:
UPDATE deposit_management
SET deposit_status = #{depositStatus},
    update_time = SYSDATE

    , update_by = #{updateBy}

WHERE id IN

    #{id}
